#!/usr/bin/env python3
"""Afterstreet foodservice pack, version 1 (26 October 2026): everything a kitchen, a counter and a dining room need to run, for the businesses the Springfield map has most of:
restaurants (about 580 mapped), fast food (545), cafes, bars, convenience stores, bakeries, butchers, delis, ice cream. Writes assets/shaped/foodservice.js.
Run: python3 assets/shaped/src/foodservice.py

models.foodservice.<name>: stands on the floor at the centre of its base, front facing +Z (the side the staff or the customer uses is in info[name].use), metres.
sizes[name] = [width, depth, height] (as in interiors.sizes) and info[name] adds the footprint, `use` (who stands where), `powered` (draws power: dead when the grid is down), `water` (needs a water supply),
`holds` (what a search of it can give) and `note`. Hoods and shelves that hang from the ceiling or wall start at their own height, so place them at y = 0 as given.
Colour names are in the palette; nothing uses slots."""
from bizkit import *
P = {'ice': '#bfe0ee', 'concrete': '#9a9a94', 'steelD': '#3a3d42', 'ss': '#b9bec2', 'ssD': '#8e949a', 'ssL': '#d6dadc', 'black': '#1f2024', 'steel': '#4a4d52', 'metal': '#8f969e', 'metalD': '#5b6168', 'chrome': '#c8c8c2', 'white': '#e2ddd2', 'cream': '#d8cfb6', 'tile': '#cfd4d2',
     'glass': '#9bb3ba', 'glassD': '#3c4a52', 'wood': '#8a6a46', 'woodD': '#6a5034', 'woodL': '#b08c62', 'red': '#b8322a', 'redD': '#7a2a24', 'yellow': '#d8b030', 'orange': '#d0702a', 'green': '#4c6a44', 'blue': '#3e5a7a', 'pink': '#d890a0',
     'brick': '#8a4a38', 'brickD': '#6a3a2c', 'flame': '#ff9a40', 'fry': '#c89038', 'oil': '#4a3a22', 'rubber': '#26262a', 'screen': '#1a1e22', 'screenOn': '#7acaa0', 'lampOn': '#ffd890', 'paper': '#e8e0c8', 'plastic': '#c9c3b6',
     'meat': '#a83a3a', 'meatL': '#d07070', 'fat': '#e8d8c8', 'dough': '#d8c090', 'bread': '#b88040', 'breadD': '#8a5a2a', 'choc': '#5a3a2a', 'straw': '#d86a7a', 'vanilla': '#f0e4b8', 'mint': '#8ac8a0', 'cone': '#c8964a',
     'cup': '#e8e4da', 'neonR': '#ff5a5a', 'neonB': '#6aa8ff', 'beer': '#d8a030', 'keg': '#a8acb0', 'tank': '#b8b8b0', 'tankW': '#d8d8d0', 'cardboard': '#a8865a', 'tag': '#e8d870', 'mat': '#34363a', 'salad': '#6a9a48', 'tomato': '#c84a30'}
p = Pack('foodservice', 'foodservice'); R = p.reg
def I(**k): return k
# ---------------------------------------------------------------- cooking line
def fryer(n=2):
    w = 0.45*n + 0.1; o = [bx(0, 0, 0, w, 0.85, 0.8, 'ss'), bx(0, 0.85, -0.3, w, 0.4, 0.2, 'ssD'), bx(0, 0.18, 0.41, w - 0.1, 0.5, 0.02, 'black')]
    for i in range(n):
        x = (i - (n - 1)/2)*0.45; o += [bx(x, 0.84, 0.05, 0.36, 0.05, 0.5, 'fry'), bx(x, 0.89, 0.3, 0.04, 0.04, 0.35, 'black'), bx(x, 0.88, 0.0, 0.3, 0.1, 0.34, 'metalD')]
    return o
R('fryer_bank', fryer(3), 'a three-vat deep fryer with baskets: the heart of fast food; hot oil, can start a grease fire', use='staff at +z', powered=True, water=False, holds=['cooking_oil', 'fries'])
R('fryer_single', fryer(1), 'a single countertop-height fryer for a small kitchen or a bar', use='staff at +z', powered=True, holds=['cooking_oil'])
R('flat_top_grill', [bx(0, 0, 0, 1.2, 0.85, 0.75, 'ss'), bx(0, 0.85, 0.0, 1.2, 0.05, 0.7, 'steel'), bx(0, 0.9, -0.34, 1.2, 0.12, 0.04, 'ssD')] + [cy(-0.45 + 0.3*i, 0.5, 0.39, 0.06, 0.06, 0.04, 'black') for i in range(4)] + [bx(0.2, 0.9, 0.05, 0.4, 0.02, 0.3, 'fry')], 'a griddle: burgers, eggs, pancakes; the rail at the back catches grease', use='staff at +z', powered=True, holds=['griddle_scraper'])
